import * as T from './assets/vendor/three.module.js';
export class MenuArt {
 constructor(canvas){this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false});this.renderer.setSize(1600,900);this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.25;this.scene=new T.Scene();this.scene.background=new T.Color('#193c40');this.scene.fog=new T.Fog('#193c40',45,95);this.camera=new T.PerspectiveCamera(37,16/9,.1,150);this.camera.position.set(-8,5,-12);this.camera.lookAt(-2,2.2,7);this.scene.add(new T.HemisphereLight('#d4fff0','#14282c',2));const light=new T.DirectionalLight('#ffe4ae',4);light.position.set(-12,16,-9);this.scene.add(light);const blue=new T.DirectionalLight('#78c8cc',2);blue.position.set(8,7,12);this.scene.add(blue);this.train=new T.Group();this.scene.add(this.train);this.box=new T.BoxGeometry(1,1,1);this.materials=[];this.materialCache=new Map();this.setupStation();}
 mat(color,metal=.0){const key=color+'|'+metal;if(this.materialCache.has(key))return this.materialCache.get(key);const m=new T.MeshStandardMaterial({color,metalness:metal,roughness:metal?.35:.8});this.materials.push(m);this.materialCache.set(key,m);return m;}
 boxAt(parent,x,y,z,w,h,d,mat){const m=new T.Mesh(this.box,mat);m.position.set(x,y,z);m.scale.set(w,h,d);parent.add(m);return m;}
 setupStation(){const floor=this.mat('#435557'),rail=this.mat('#9aa8a3',.8),dark=this.mat('#263c3e'),roof=this.mat('#566c66'),platform=this.mat('#84958b');this.boxAt(this.scene,0,-.15,15,130,.2,150,floor);for(const x of[-.55,.55,4.45,5.55])this.boxAt(this.scene,x,.08,15,.07,.14,150,rail);for(let z=-35;z<70;z+=.9)for(const x of[0,5])this.boxAt(this.scene,x,0,z,2.1,.1,.16,dark);this.boxAt(this.scene,-4,.5,16,4,1,80,platform);this.boxAt(this.scene,-4,7,16,6,.18,80,roof);for(let z=3;z<65;z+=9)this.boxAt(this.scene,-4,4,z,.15,6,.15,platform);}
 draw(meta){for(const child of [...this.train.children]){this.train.remove(child);child.traverse(o=>{if(o.geometry&&o.geometry!==this.box)o.geometry.dispose();});}const body=this.mat('#d1d9d8',.7),stripe=this.mat(meta.trainColor??meta.color,.3),dark=this.mat('#172d35',.35),glass=this.mat('#233c47',.5),roof=this.mat('#7c8f92',.4),lamp=this.mat('#fff0bb'),black=this.mat('#17232c'),red=this.mat('#b34b4a');
  for(let car=0;car<3;car++){const z=car*20.8+10.1;this.boxAt(this.train,0,2.35,z,2.9,3.35,20,body);this.boxAt(this.train,0,4.07,z,2.8,.2,19.8,roof);this.boxAt(this.train,0,1.04,z,2.2,.6,16,black);for(const side of[-1,1]){this.boxAt(this.train,side*1.456,1.85,z,.022,.38,20,stripe);this.boxAt(this.train,side*1.46,3.55,z,.023,.08,20,stripe);for(let k=0;k<7;k++){const zz=z-8.2+k*2.65;this.boxAt(this.train,side*1.468,2.95,zz,.025,.95,1.9,glass);if(k%2===0){this.boxAt(this.train,side*1.475,2.35,zz,.029,2.35,1.5,roof);this.boxAt(this.train,side*1.49,2.94,zz,.025,.86,1.1,glass);this.boxAt(this.train,side*1.51,2.3,zz,.02,2.28,.035,black);}}for(const zz of[z-6.7,z+6.7])for(const x of[-1,1]){const wheel=new T.Mesh(new T.CylinderGeometry(.42,.42,.22,12),black);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.51,zz);this.train.add(wheel);}}
  }
  this.boxAt(this.train,0,2.45,-.02,2.93,3.05,.1,dark);this.boxAt(this.train,0,1.24,-.09,2.9,.7,.15,body);this.boxAt(this.train,0,1.65,-.11,2.86,.35,.1,stripe);const modern=meta.vehicle==='e235'||meta.vehicle==='323';if(modern){this.boxAt(this.train,0,2.5,-.12,2.6,1.9,.06,glass);this.boxAt(this.train,0,3.65,-.14,2.7,.43,.06,stripe);}else{for(const x of[-.88,.88])this.boxAt(this.train,x,2.85,-.13,.9,1.2,.06,glass);this.boxAt(this.train,0,2.3,-.16,.55,2.4,.12,body);this.boxAt(this.train,0,2.8,-.24,.4,.9,.02,glass);}
  for(const x of[-1.08,1.08]){this.boxAt(this.train,x,3.64,-.2,.28,.18,.06,lamp);this.boxAt(this.train,x,1.35,-.2,.25,.12,.05,red);}this.boxAt(this.train,0,.64,-.22,.5,.25,.55,black);this.boxAt(this.train,0,3.7,-.22,1.3,.25,.03,black);this.renderer.render(this.scene,this.camera);
 }
}
export class SimpleAudio {
 constructor(volume=.65){const AC=globalThis.AudioContext??globalThis.webkitAudioContext;this.context=new AC();this.master=this.context.createGain();this.master.gain.value=volume;this.master.connect(this.context.destination);this.sources=new Set();this.generation=0;this.context.resume();this.loop=this.context.createOscillator();this.loop.type='triangle';this.gain=this.context.createGain();this.gain.gain.value=0;this.loop.connect(this.gain);this.gain.connect(this.master);this.loop.start();}
 setVolume(v){this.master.gain.value=v;}
 async playEffect(name){const duration=name==='close'?2.7:name==='open'?1.5:name==='whistle'?1.3:name.startsWith('horn')?.8:.06,source=this.context.createOscillator(),gain=this.context.createGain(),t=this.context.currentTime,generation=this.generation;source.type=name==='whistle'?'sine':'triangle';source.frequency.value=name==='whistle'?1400:name.startsWith('horn')?440:name==='close'?230:310;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(name==='notch'?.04:.13,t+.035);gain.gain.setValueAtTime(name==='notch'?.04:.13,t+duration-.04);gain.gain.linearRampToValueAtTime(0,t+duration);source.connect(gain);gain.connect(this.master);this.sources.add(source);return new Promise(resolve=>{source.onended=()=>{this.sources.delete(source);gain.disconnect();resolve(generation===this.generation);};source.start();source.stop(t+duration);});}
 update(speed,notch,dt,{doors=false}={}){const t=this.context.currentTime;this.loop.frequency.setTargetAtTime(44+speed*3.6,t,.1);this.gain.gain.setTargetAtTime(doors?0:Math.min(.055,speed*.001)*(notch>0?1:.4),t,.1);}
 async setPaused(v){if(v)await this.context.suspend();else await this.context.resume();}
 stop(){this.generation++;for(const s of this.sources){try{s.stop();}catch{}}this.sources.clear();this.gain.gain.value=0;}
 async dispose(){this.stop();try{this.loop.stop();await this.context.close();}catch{}}
}
export function drawSimpleCab(canvas,state,recipe,color){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,1600,900);const g=ctx.createLinearGradient(0,650,0,900);g.addColorStop(0,'#303f43');g.addColorStop(.06,'#5c6b6b');g.addColorStop(.09,'#233238');g.addColorStop(1,'#0e1d24');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,710);ctx.lineTo(260,674);ctx.lineTo(1340,674);ctx.lineTo(1600,710);ctx.lineTo(1600,900);ctx.lineTo(0,900);ctx.fill();ctx.strokeStyle='#7d9492';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(260,674);ctx.lineTo(1340,674);ctx.stroke();ctx.fillStyle='#09171d';ctx.fillRect(350,710,900,170);ctx.strokeStyle='#637b7e';ctx.strokeRect(350,710,900,170);
 function gauge(x,y,value,max,title){ctx.fillStyle='#becbbf';ctx.beginPath();ctx.arc(x,y,64,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#132c35';ctx.lineWidth=2;for(let n=0;n<=max;n+=max/12){const a=(-130+n/max*260)*Math.PI/180;ctx.beginPath();ctx.moveTo(x+Math.sin(a)*48,y-Math.cos(a)*48);ctx.lineTo(x+Math.sin(a)*58,y-Math.cos(a)*58);ctx.stroke();}const a=(-130+Math.min(1,value/max)*260)*Math.PI/180;ctx.strokeStyle='#b33d3b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x-Math.sin(a)*12,y+Math.cos(a)*12);ctx.lineTo(x+Math.sin(a)*50,y-Math.cos(a)*50);ctx.stroke();ctx.fillStyle='#132b30';ctx.font='13px sans-serif';ctx.textAlign='center';ctx.fillText(title,x,y+27);ctx.beginPath();ctx.arc(x,y,5,0,7);ctx.fill();}
 gauge(450,795,Math.max(0,-state.notch)*45,900,'kPa');gauge(625,795,state.v*3.6,160,'km/h');ctx.fillStyle='#021419';ctx.fillRect(750,740,290,112);ctx.strokeStyle='#33595b';ctx.strokeRect(750,740,290,112);ctx.textAlign='left';ctx.fillStyle=color;ctx.font='bold 20px sans-serif';ctx.fillText(recipe.name,770,768);ctx.font='14px monospace';ctx.fillStyle='#b6ddd0';ctx.fillText(`${recipe.playableSpecs.carCount} CARS    LOCAL`,770,797);ctx.fillText(state.doors?'DOOR OPEN':'DOOR CLOSED',770,825);ctx.fillStyle=state.doors?'#50351a':'#ffde67';ctx.beginPath();ctx.arc(1120,765,14,0,7);ctx.fill();ctx.fillStyle='#b6c5bc';ctx.font='13px sans-serif';ctx.fillText('戸閉',1106,802);
}
